style:
@font-face{font-family:'Poppins';font-style:normal;font-weight:400;font-display:swap;src:url('/assets/upande_livestock/fonts/poppins-400.woff2') format('woff2')}
@font-face{font-family:'Poppins';font-style:normal;font-weight:500;font-display:swap;src:url('/assets/upande_livestock/fonts/poppins-500.woff2') format('woff2')}
@font-face{font-family:'Poppins';font-style:normal;font-weight:600;font-display:swap;src:url('/assets/upande_livestock/fonts/poppins-600.woff2') format('woff2')}
@font-face{font-family:'Poppins';font-style:normal;font-weight:700;font-display:swap;src:url('/assets/upande_livestock/fonts/poppins-700.woff2') format('woff2')}

.uld{
  --ink:#0a0a0a; --ink-3:#3a3a34; --ink-4:#5a5a52; --ink-mute:#8a8780;
  --bg:#f4f3ef; --surface:#ffffff; --hairline:rgba(10,10,10,0.06);
  --shadow-card:0 1px 0 rgba(10,10,10,0.04),0 8px 32px -16px rgba(10,10,10,0.10);
  --shadow-hover:0 1px 0 rgba(10,10,10,0.06),0 24px 48px -24px rgba(10,10,10,0.18);
  --signal:#228883;
  --grad-ink:linear-gradient(135deg,#0a0a0a 0%,#3a3a34 100%);
  --sans:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  font-family:var(--sans); color:var(--ink-3); line-height:1.55; padding:8px 4px 24px;
}
.uld *{box-sizing:border-box}

.uld-head{display:grid;grid-template-columns:1fr auto;align-items:end;gap:32px;margin-bottom:28px}
.uld-eyebrow{font:500 11px var(--sans);text-transform:uppercase;letter-spacing:2.2px;color:var(--ink-mute);margin-bottom:10px;display:inline-flex;align-items:center;gap:10px}
.uld-eyebrow::before{content:"";width:18px;height:1px;background:var(--ink-3)}
.uld-title{font:600 40px/1.05 var(--sans);color:var(--ink);letter-spacing:-1.2px;margin:0}
.uld-sub{margin-top:8px;font-size:14px;color:var(--ink-4)}
.uld-datepill{display:inline-flex;align-items:center;gap:8px;background:var(--surface);border-radius:999px;padding:10px 16px;font:500 12px var(--sans);color:var(--ink);box-shadow:var(--shadow-card)}

.uld-tabs{display:inline-flex;gap:4px;margin-bottom:28px;background:rgba(10,10,10,0.04);padding:5px;border-radius:999px;max-width:100%;overflow-x:auto}
.uld-tab{background:transparent;border:0;font:500 13px var(--sans);color:var(--ink-4);padding:10px 18px;border-radius:999px;cursor:pointer;white-space:nowrap;transition:all .2s}
.uld-tab:hover:not(:disabled){color:var(--ink)}
.uld-tab.on{background:var(--grad-ink);color:#fafaf6;box-shadow:0 4px 14px rgba(10,10,10,0.20)}
.uld-tab:disabled{opacity:.45;cursor:not-allowed}

.uld-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-bottom:18px}
.uld-kpi{background:var(--surface);border-radius:20px;padding:26px 28px;box-shadow:var(--shadow-card);transition:all .25s}
.uld-kpi:hover{transform:translateY(-3px);box-shadow:var(--shadow-hover)}
.uld-kpi-label{font:500 11px var(--sans);text-transform:uppercase;letter-spacing:1.8px;color:var(--ink-mute);margin-bottom:14px}
.uld-kpi-value{font:600 42px/1 var(--sans);color:var(--ink);letter-spacing:-1.4px;font-variant-numeric:tabular-nums}
.uld-kpi-unit{font:400 13px var(--sans);color:var(--ink-mute);margin-top:8px}

.uld-row2{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-bottom:18px}
.uld-card{background:var(--surface);border-radius:24px;box-shadow:var(--shadow-card);margin-bottom:0}
.uld-card-pad{padding:26px 30px}
.uld-card-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:22px;gap:24px}
.uld-card-head h3{margin:0;font:600 17px var(--sans);color:var(--ink);letter-spacing:-.4px}
.uld-meta{font:500 12px var(--sans);color:var(--ink-mute)}
.uld-legend{display:flex;gap:16px;font-size:12px;color:var(--ink-mute)}
.uld-legend span{display:inline-flex;align-items:center;gap:6px}
.uld-legend i{width:16px;height:3px;border-radius:2px;background:var(--ink)}
.uld-chart{width:100%;height:240px;display:block}

.uld-list{display:flex;flex-direction:column}
.uld-lrow{display:grid;grid-template-columns:36px 1fr auto;gap:14px;padding:13px 8px;border-bottom:1px solid var(--hairline);align-items:center;border-radius:10px}
.uld-lrow:last-child{border-bottom:0}
.uld-rank{font:500 13px var(--sans);color:var(--ink-mute);width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:rgba(10,10,10,0.04)}
.uld-rank.lead{background:var(--grad-ink);color:#fafaf6}
.uld-lname{font:600 14px var(--sans);color:var(--ink)}
.uld-lmeta{font-size:12px;color:var(--ink-mute);margin-top:2px}
.uld-lqty{font:600 16px var(--sans);color:var(--ink);font-variant-numeric:tabular-nums}

.uld-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}
.uld-tile{background:var(--surface);border:1px solid var(--hairline);border-radius:20px;padding:22px 24px;transition:all .2s}
.uld-tile:hover{transform:translateY(-2px);box-shadow:var(--shadow-hover)}
.uld-tile-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}
.uld-tile-name{font:600 15px var(--sans);color:var(--ink);letter-spacing:-.2px}
.uld-tile-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.uld-tile-stats small{font:500 10px var(--sans);text-transform:uppercase;letter-spacing:1px;color:var(--ink-mute);display:block;margin-bottom:2px}
.uld-tile-stats b{font:600 18px var(--sans);color:var(--ink);font-variant-numeric:tabular-nums}

.uld-empty{padding:28px 0;text-align:center;color:var(--ink-mute);font-size:13px}

@media (max-width:1000px){.uld-row2{grid-template-columns:1fr}.uld-title{font-size:32px}}

script:
// Custom HTML Block script. Frappe injects `root_element` (the block's DOM
// root) into scope. Fetch livestock stats and render, mirroring the SCP
// dashboard block's fetch(+CSRF) pattern.
var root = (typeof root_element !== "undefined" && root_element)
  ? root_element
  : document.querySelector(".uld");
if (root) {
  (function () {
    function fmt(n) {
      if (n === null || n === undefined) return "—";
      return Number(n).toLocaleString();
    }
    function esc(s) {
      var e = document.createElement("div");
      e.textContent = s == null ? "" : String(s);
      return e.innerHTML;
    }
    function q(sel) { return root.querySelector(sel); }

    fetch("/api/method/upande_livestock.api.workspace.get_livestock_workspace_stats", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Frappe-CSRF-Token": (window.frappe && frappe.csrf_token) || "",
      },
      body: "{}",
    })
      .then(function (r) { return r.json(); })
      .then(function (res) { render((res && res.message) || {}); })
      .catch(function () { render({}); });

    function render(d) {
      var k = d.kpis || {};
      if (q('[data-kpi="active_animals"]')) q('[data-kpi="active_animals"]').textContent = fmt(k.active_animals);
      if (q('[data-unit="herds"]')) q('[data-unit="herds"]').textContent = "across " + fmt(k.herds_count) + " herds";
      if (q('[data-kpi="milk_value"]')) q('[data-kpi="milk_value"]').textContent = fmt(k.milk_value);
      if (q('[data-unit="milk"]')) q('[data-unit="milk"]').textContent = "kg · " + (k.milk_date || "no data");
      if (q('[data-kpi="health_events"]')) q('[data-kpi="health_events"]').textContent = fmt(k.health_events);
      if (q('[data-kpi="births"]')) q('[data-kpi="births"]').textContent = fmt(k.births);
      if (q("[data-sub]")) q("[data-sub]").textContent =
        fmt(k.active_animals) + " animals · " + fmt(k.herds_count) + " herds · " + fmt(k.milk_value) + " kg latest milk";
      if (q("[data-date]")) q("[data-date]").textContent = "Milk · " + (k.milk_date || "—");

      drawChart(q("[data-chart]"), d.milk_series || []);

      var top = d.top_herds || [];
      if (q("[data-top-meta]")) q("[data-top-meta]").textContent = top.length ? top.length + " herds · 30d" : "no milk records";
      if (q("[data-top-list]")) q("[data-top-list]").innerHTML = top.length
        ? top.map(function (h, i) {
            return '<div class="uld-lrow"><div class="uld-rank ' + (i === 0 ? "lead" : "") +
              '">' + (i + 1) + '</div><div><div class="uld-lname">' + esc(h.name) +
              '</div><div class="uld-lmeta">last 30 days</div></div><div class="uld-lqty">' +
              fmt(h.yield) + " kg</div></div>";
          }).join("")
        : '<div class="uld-empty">No milk recordings in the last 30 days</div>';

      var herds = d.herds || [];
      if (q("[data-herd-meta]")) q("[data-herd-meta]").textContent = herds.length + " herds";
      if (q("[data-herd-tiles]")) q("[data-herd-tiles]").innerHTML = herds.length
        ? herds.map(function (h) {
            return '<div class="uld-tile"><div class="uld-tile-head"><div class="uld-tile-name">' +
              esc(h.name) + '</div></div><div class="uld-tile-stats">' +
              '<div><small>Animals</small><b>' + fmt(h.animals) + "</b></div>" +
              '<div><small>Milkers</small><b>' + fmt(h.milkers) + "</b></div>" +
              '<div><small>Avg yield</small><b>' + (h.avg_yield ? fmt(h.avg_yield) + " kg" : "—") + "</b></div>" +
              '<div><small>Pregnant</small><b>' + fmt(h.pregnant) + "</b></div>" +
              "</div></div>";
          }).join("")
        : '<div class="uld-empty">No herds</div>';
    }

    function drawChart(svg, series) {
      if (!svg) return;
      if (!series.length) {
        svg.innerHTML =
          '<line x1="0" y1="180" x2="600" y2="180" stroke="rgba(10,10,10,0.08)" stroke-width="2"/>' +
          '<text x="300" y="120" text-anchor="middle" fill="#8a8780" font-size="13">No milk data yet</text>';
        return;
      }
      var W = 600, H = 240, pad = 12;
      var ys = series.map(function (p) { return p.yield; });
      var max = Math.max.apply(null, ys) || 1;
      var n = series.length;
      function x(i) { return n === 1 ? W / 2 : pad + (i * (W - 2 * pad)) / (n - 1); }
      function y(v) { return H - pad - (v / max) * (H - 2 * pad); }
      var pts = series.map(function (p, i) { return [x(i), y(p.yield)]; });
      var line = pts.map(function (p, i) { return (i ? "L" : "M") + p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" ");
      var area = line + " L" + x(n - 1).toFixed(1) + "," + H + " L" + x(0).toFixed(1) + "," + H + " Z";
      var grid = "";
      [40, 100, 160, 220].forEach(function (gy) {
        grid += '<line x1="0" y1="' + gy + '" x2="600" y2="' + gy + '" stroke="rgba(10,10,10,0.05)" stroke-width="1"/>';
      });
      svg.innerHTML =
        '<defs><linearGradient id="uldGrad" x1="0" y1="0" x2="0" y2="1">' +
        '<stop offset="0%" stop-color="#0a0a0a" stop-opacity=".18"/>' +
        '<stop offset="100%" stop-color="#0a0a0a" stop-opacity="0"/></linearGradient></defs>' +
        grid +
        '<path d="' + area + '" fill="url(#uldGrad)"/>' +
        '<path d="' + line + '" fill="none" stroke="#0a0a0a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>' +
        pts.map(function (p) {
          return '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="3.5" fill="#228883"/>';
        }).join("");
    }
  })();
}
